class Solution {
public:
    int countServers(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<int> rowCnt(m, 0), colCnt(n, 0);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1) {
                    rowCnt[r]++;
                    colCnt[c]++;
                }
            }
        }
        int ans = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1 && (rowCnt[r] > 1 || colCnt[c] > 1)) {
                    ans++;
                }
            }
        }
        return ans;
    }
};

