    const m = grid.length, n = grid[0].length;
    const rowCnt = new Array(m).fill(0);
    const colCnt = new Array(n).fill(0);
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (grid[r][c] === 1) {
                rowCnt[r]++;
                colCnt[c]++;
            }
        }
    }
